import {preview,advance,publicDefenseProjection,Lifetime,operationCatalog} from './sdk/workflow.js';
const key='redline-demo-v1';const defaults={selected:'v',target:'e',turn:0,round:3,ammo:8,weapon:'pistol',mode:'single',role:'player',compact:false,collapsed:false,motion:true,scale:1,knownDv:true,hidden:false,many:false,empty:false,long:false,panel:null,netFlat:false,position:'right',request:null,applied:[],appliedCount:0};
let state;try{state={...defaults,...JSON.parse(localStorage.getItem(key)||'{}')}}catch{state={...defaults}};
const params=new URLSearchParams(location.search);if(params.has('reset'))state={...defaults};const screen=params.get('screen');if(screen){state.panel=screen==='overview'||screen==='initiative'?null:screen;if(screen==='gm')state.role='gm';if(screen==='initiative')state.compact=true;if(['defense','result'].includes(screen))state.request={id:'DEMO-031',phase:screen==='defense'?'awaiting-defense':'resolved',revision:2,attacker:'Вега',target:'Охранник',result:'hit'};}
let lifetime=new Lifetime();let toastTimer;const app=document.querySelector('#app');const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const actors={v:{name:'Вега',role:'Соло · ранг 4',hp:38,max:50,img:'vega.svg',weapon:true},n:{name:'Никс',role:'Нетраннер · ранг 4',hp:30,max:35,img:'nyx.svg',weapon:false},e:{name:'Охранник',role:'Противник',img:'guard.svg'}};
function save(){localStorage.setItem(key,JSON.stringify(state))}function say(text){clearTimeout(toastTimer);document.querySelector('.toast')?.remove();const d=document.createElement('div');d.className='toast';d.setAttribute('role','status');d.textContent=text;document.body.append(d);toastTimer=setTimeout(()=>d.remove(),4500)}
function selected(){return actors[state.selected]}function prepared(){if(state.mode==='aimed')return {ok:false,reason:'Прицельный режим показан для проверки параметров. Демо-исполнение поддерживает только одиночную атаку.'};return preview({ammo:state.ammo,weapon:selected()?.weapon&&state.weapon!=='none',target:state.target&&!state.hidden,knownDv:state.knownDv})}
function button(action,label,cls='',disabled=false){return `<button data-action="${action}" class="${cls}" ${disabled?'disabled':''}>${label}</button>`}function row(label,val){return `<div class="row"><span class="muted">${label}</span><b>${val}</b></div>`}
function panelHeader(tag,title){return `<header><span class="tag">${tag}</span>${button('close','✕','small')}</header><h1 id="panel-title">${title}</h1>`}
function attackPanel(){let p=prepared();return `<aside class="sheet" aria-labelledby="panel-title">${panelHeader('01 / Подготовка','Подготовить атаку')}<div class="step"><span class="active">Параметры</span> → <span>Защита</span> → <span>Результат</span></div><span class="tag">Цель · видимая на карте</span><h2>${state.hidden||!state.target?'Не выбрана':'Охранник'}</h2><p class="muted">Точные ресурсы противника недоступны игроку.</p><div class="divider"></div><label for="fire-mode" class="tag">Режим оружия</label><select id="fire-mode" data-field="mode" class="full"><option value="single" ${state.mode==='single'?'selected':''}>Одиночный</option><option value="aimed" ${state.mode==='aimed'?'selected':''}>Прицельный · голова</option></select>${row('Дистанция (демо)','10 м')}${row('Таблица DV','Handgun · 7–12 м')}${row('DV',state.knownDv?'15':'Не определён')}${row('REF + Handgun','8 + 6')}${row('Режим',state.mode==='aimed'?'−8 · ROF 1':'Одиночный · ROF 2')}${row('Модификаторы (демо)','Нет')}${row('Расход при выполнении','1 патрон')}<div class="hint ${p.ok?'':'error'}">${p.ok?'Это предварительный просмотр. Патроны ещё не расходуются. Укрытие не преобразуется в условный бонус к DV.':esc(p.reason)}</div><p class="muted">Учебный сценарий, без системного броска. Демо фиксирует результат для проверки интерфейса.</p>${button('execute','Выполнить демо-атаку →','primary full',!p.ok)}${button('close','Отменить подготовку','full')}</aside>`}
function defensePanel(){let r=state.request||{id:'DEMO',phase:'awaiting-defense',attacker:'Вега',target:'Охранник'};let pub=publicDefenseProjection(r);return `<aside class="sheet defense" aria-labelledby="panel-title">${panelHeader('02 / Предпросмотр клиента защиты','Входящая атака')}<div class="step"><span>Подготовлено</span> → <span class="active">Выбор защиты</span> → <span>Результат</span></div><div class="tag">${esc(pub.id)} · ожидает решения</div><h2>${esc(pub.attacker)} → ${esc(pub.target)}</h2><p class="muted">Предпросмотр отдельного получателя. В Foundry эту панель видит контролирующий цель участник.</p><div class="hint">Результат атаки пока не раскрыт. Доступность уклонения здесь задана демонстрационными данными (REF 8).</div><div class="choices">${button('evade','Уклониться <small>Демонстрация встречного броска Evasion</small>','primary')}${button('decline','Не уклоняться <small>Проверить попадание по известному DV</small>')}</div>${row('Срок ответа','Не ограничен')}${row('Статус','Ожидание участника')}<p class="muted">При отключении участника запрос остаётся ожидающим. Нет автоматического попадания.</p>${button('reconnect','Имитировать переподключение','full')}</aside>`}
function resultPanel(){let applied=state.request?.phase==='applied',dodged=state.request?.result==='dodged';return `<aside class="sheet result" aria-labelledby="panel-title">${panelHeader('03 / Разрешённый демо-результат','Результат атаки')}<div class="result-title">${dodged?'Уклонение успешно':'Попадание'}</div><p class="muted">Вега → Охранник · тяжёлый пистолет</p>${row('Демо-атака',state.mode==='aimed'?'18 (фиксировано)':'18 (фиксировано)')}${row(dodged?'Демо-защита':'DV',dodged?'19 (фиксировано)':'15')}${row('Системный бросок','Не выполнялся')}<div class="divider"></div>${dodged?'<div class="hint">Урон не применяется. Патрон был потрачен при выполнении атаки.</div>':`${row('Демо-урон','14 · тело')}${row('Демо-броня',state.role==='gm'?'SP 11 → 10':'Точные значения скрыты')}${row('Демо-HP',state.role==='gm'?'35 → 32':'Точные значения скрыты')}<div class="hint">Расчёт здесь иллюстративный. Состояние мира не меняется; системный адаптер отсутствует.</div>`}<div role="status" class="tag">${applied?'Изменение демо-состояния применено один раз':'Ожидает применения GM в демо'}</div>${button('apply',applied?'Уже применено':dodged?'Завершить демо-операцию':'Применить демо-изменение','primary full',applied||state.role!=='gm')}<p class="muted">${state.role==='gm'?'В этой вкладке повторный вызов с тем же ID не применится снова.':'Игрок не применяет чужой урон. Переключитесь в GM для учебного сценария.'}</p>${button('next','Следующий ход','full',!applied)}</aside>`}
function gmPanel(){return `<aside class="sheet gm" aria-labelledby="panel-title">${panelHeader('GM / Контроль исполнения','Пульт ведущего')}<p class="muted">Отдельное представление полномочий. Переключатель роли в прототипе не является системой авторизации.</p>${row('Ответственный исполнитель','GM-A · демонстрация')}${row('Текущий запрос',state.request?.id||'Нет')}${row('Фаза',state.request?.phase||'Нет активной операции')}${row('Демо-применений',state.appliedCount)}<div class="divider"></div><h3>Требует внимания</h3><div class="issue"><span class="tag danger">Нет достоверного DV</span><h2>Не разрешать как попадание</h2><p>Выберите таблицу дальности или завершите спорную операцию вручную в штатной системе.</p></div><div class="issue"><span class="tag yellow">Участник отключён</span><h2>Сохранить ожидание</h2><p>GM может отменить запрос после проверки состояния. Нет фонового сервера в клиенте.</p></div>${button('result','Открыть текущий результат','full',!state.request||!['resolved','applied'].includes(state.request.phase))}${button('cancel','Отменить демо-запрос','full',!state.request)}<div class="hint">Штатные Combat и Combatant остаются источником истины. Обычный трекер — резервный интерфейс.</div></aside>`}
function netPanel(){return `<aside class="sheet net" aria-labelledby="panel-title">${panelHeader('NET / Раскрытые данные','Внутри архитектуры')}<p class="purple">Никс · Interface 4 · физическое тело остаётся на карте</p><div class="hint">Только раскрытая часть демонстрационной архитектуры. Действия не подключены к системе.</div><div class="nodes ${state.netFlat?'flat':''}"><div class="node"><span class="tag purple">Уровень 1 · раскрыт</span><h2>Пароль</h2><p class="muted">Доступ открыт · учебное состояние</p></div><div class="node"><span class="tag purple">Уровень 2 · текущий</span><h2>Файл / Архив перевозок</h2><p class="muted">Доступна идентификация</p></div><div class="node locked"><h3>Дальнейшее содержимое неизвестно</h3><p>Количество и содержимое этажей не показаны.</p></div></div><div class="net-grid">${button('net-demo','Eye-Dee · демо')}${button('net-demo','Scanner · демо')}${button('net-demo','Slide · демо')}${button('net-demo','Jack Out · демо')}</div>${row('Экономика NET','Не автоматизирована')}${button('flat',state.netFlat?'Показать связи':'Плоский список','full')}<p class="muted">Счётчик действий должен поступать из адаптера правил, а не из анимации. Это не запас реакций и не кулдаун.</p></aside>`}
function settings(){return `<aside class="settings" aria-label="Демо-условия"><h2>Проверка состояний</h2>${['compact','motion','knownDv','hidden','many','empty','long'].map((k,i)=>`<label><input type="checkbox" data-field="${k}" ${state[k]?'checked':''}>${['Компактный режим','Анимации','Известный DV','Скрытая цель','24 участника','Пустой бой','Длинные имена'][i]}</label>`).join('')}<label>Панель <select data-field="position"><option value="right" ${state.position==='right'?'selected':''}>Справа</option><option value="left" ${state.position==='left'?'selected':''}>Слева</option></select></label><label>Масштаб <select data-field="scale">${[1,1.15,1.25].map(x=>`<option ${state.scale===x?'selected':''} value="${x}">${x*100}%</option>`).join('')}</select></label>${button('empty-ammo','Опустошить магазин','full')}${button('reset','Сбросить демо','full')}${button('close','Закрыть','full')}</aside>`}
function render(){lifetime.close();lifetime=new Lifetime();save();document.body.className=[state.compact?'compact':'',state.collapsed?'collapsed':'',state.motion?'':'no-motion',state.panel&&state.panel!=='settings'?'has-panel':'',state.position==='left'?'panel-left':''].join(' ');document.documentElement.style.setProperty('--ui',state.scale);let a=selected();let units=state.empty?[]:state.many?Array.from({length:24},(_,i)=>({id:i===0?'v':i===1?'n':'e',name:i<2?actors[i===0?'v':'n'].name:`Участник ${i+1}`,score:22-i})):['v','n','e'].map((id,i)=>({id,name:actors[id].name,score:[22,18,14][i]}));let panel=state.panel==='attack'?attackPanel():state.panel==='defense'?defensePanel():state.panel==='result'?resultPanel():state.panel==='gm'&&state.role==='gm'?gmPanel():state.panel==='net'?netPanel():state.panel==='settings'?settings():'';
app.innerHTML=`<header class="top"><div class="brand">REDLINE<span> / </span>COMBAT <span class="tag">Astra UI study</span></div><nav aria-label="Режимы">${button('overview','Бой')}${button('net','NET')}${button('gm','GM',state.role==='gm'?'danger':'',state.role!=='gm')}<label class="sr-only" for="role">Роль демонстрации</label><select id="role" data-field="role"><option value="player" ${state.role==='player'?'selected':''}>Игрок · демо</option><option value="gm" ${state.role==='gm'?'selected':''}>GM · демо</option></select>${button('settings','Настройки')}</nav></header><section class="initiative" aria-label="Очередь инициативы"><div class="round"><span class="tag">РАУНД</span><strong>${String(state.round).padStart(2,'0')} <span class="yellow">/</span></strong></div><div class="queue">${units.map((u,i)=>`<button class="unit ${i===state.turn?'turn':''} ${u.id===state.selected?'selected':''}" data-select="${u.id}" title="${esc(state.long?u.name+' / «Хромированный странник северного сектора»':u.name)}" ${u.id==='e'&&state.role!=='gm'?'disabled':''}><img src="${actors[u.id].img}" alt=""><span><b>${esc(state.long?u.name+' / «Хромированный странник северного сектора»':u.name)}</b><em>${i===state.turn?'▶ Сейчас ход':i===state.turn+1?'Далее':'В очереди'}</em></span><span class="score">${u.score}</span></button>`).join('')||'<p class="muted">Бой не начат · участники отсутствуют</p>'}</div>${button('next','Завершить ход →','small',state.empty||(state.request&&!['applied'].includes(state.request.phase))||(state.role!=='gm'&&units[state.turn]?.id!==state.selected))}</section><main class="scene"><div class="notice">ЛОКАЛЬНЫЙ ПРОТОТИП · ДЕМО-ДАННЫЕ · БЕЗ БРОСКОВ FOUNDRY</div><div class="scene-label">NIGHT CITY / ДОК 09 / ТЕСТОВАЯ СЦЕНА</div><div class="legend"><span class="cyan">◉ Выбранный персонаж</span><span class="yellow">▶ Активный ход</span><span class="danger">⊕ Цель</span></div><button class="map-token ${state.selected==='v'?'chosen':''}" style="left:36%;top:43%" data-select="v" aria-label="Выбрать Вегу"><img src="vega.svg" alt=""><span>Вега · выбрана ${state.selected==='v'?'●':''}</span></button><button class="map-token ${state.selected==='n'?'chosen':''}" style="left:24%;top:53%" data-select="n" aria-label="Выбрать Никс"><img src="nyx.svg" alt=""><span>Никс</span></button>${!state.hidden?`<button class="map-token enemy ${state.target==='e'?'target':''}" style="left:59%;top:35%" data-action="target" aria-label="Выбрать целью охранника"><img src="guard.svg" alt=""><span>Охранник · цель</span></button>`:''}${state.panel==='attack'?'<div class="floating">◉ Вега → ⊕ Охранник<br><span class="muted">Демонстрационная дистанция 10 м. Препятствия проверяет адаптер; карта здесь — макет.</span></div>':''}${panel}<section class="dock" aria-label="Панель выбранного персонажа">${!a||state.empty?'<div class="empty"><h2>Выберите своего персонажа</h2><p class="muted">Бой пуст. Подготовка атаки недоступна.</p></div>':`<div class="identity"><img class="portrait" src="${a.img}" alt="Иллюстративный портрет ${a.name}"><div><span class="tag cyan">Выбранный персонаж</span><h2>${esc(state.long?a.name+' «Хромированный странник»':a.name)}</h2><span class="muted">${a.role}</span><p class="cyan">${a.hp?'Лёгкое ранение':'Ресурсы NPC · GM'}</p></div></div><div class="vitals"><span class="tag">Здоровье</span><div class="health">${a.hp||35}<small> / ${a.max||35}</small></div><div class="meter"><i></i></div><div class="armor"><span>Голова <b>11 SP</b></span><span>Тело <b>11 SP</b></span></div></div><div class="weapon"><div class="weapon-head"><span class="tag">Активное оружие</span><b>${a.weapon&&state.weapon!=='none'?String(state.ammo).padStart(2,'0'):'—'}<small class="muted"> / 08</small></b></div><label class="sr-only" for="weapon">Оружие</label><select id="weapon" data-field="weapon" ${state.request&&state.request.phase!=='applied'?'disabled':''}><option value="pistol" ${state.weapon==='pistol'?'selected':''}>${a.weapon?'Тяжёлый пистолет · 3d6 · ROF 2':'Оружие отсутствует'}</option><option value="none" ${state.weapon==='none'?'selected':''}>Без оружия</option></select><p class="muted">Стандартные патроны · одиночный</p><div class="actions">${button('attack','Подготовить атаку','primary',!a.weapon||state.weapon==='none'||state.empty||(state.request&&!['applied'].includes(state.request.phase)))}${button('reload','Перезарядить', '',!a.weapon)}</div></div>`}<div class="commands">${button('expand',state.collapsed?'Развернуть панель':'Свернуть','expand')}${button('compact',state.compact?'Расширенный вид':'Компактный вид')}${button('resume','Вернуться к запросу','',!state.request)}</div></section></main>`;
for(const el of app.querySelectorAll('[data-action]'))lifetime.on(el,'click',ev=>{if(ev.detail>1)return;act(el.dataset.action)});for(const el of app.querySelectorAll('[data-select]'))lifetime.on(el,'click',()=>{state.selected=el.dataset.select;if(state.panel==='attack')state.panel=null;render();say('Выбранный персонаж изменён. Очередь инициативы сохранена.')});for(const el of app.querySelectorAll('[data-field]'))lifetime.on(el,'change',()=>{let k=el.dataset.field;state[k]=el.type==='checkbox'?el.checked:k==='scale'?Number(el.value):el.value;if(k==='role'&&state.role==='player'&&state.panel==='gm')state.panel=null;render()});const x=app.querySelector('.sheet header button');if(x)x.setAttribute('aria-label','Закрыть контекстную панель');}
function act(action){if(['overview','close'].includes(action))state.panel=null;else if(action==='settings')state.panel='settings';else if(action==='attack'){if(!selected()?.weapon||state.request&&!['applied'].includes(state.request.phase))return;state.panel='attack'}else if(action==='execute'){if(state.request&&!['applied'].includes(state.request.phase))return;if(!prepared().ok)return say(prepared().reason);state.request={id:crypto.randomUUID(),phase:'prepared',revision:0,attacker:selected().name,target:'Охранник',mode:state.mode};state.request=advance(state.request,'execute');state.ammo-=1;state.panel='defense'}else if(action==='evade'||action==='decline'){if(state.request?.phase!=='awaiting-defense')return;state.request=advance(state.request,action);state.request.result=action==='evade'?'dodged':'hit';state.panel='result'}else if(action==='apply'){if(state.role!=='gm'||state.request?.phase!=='resolved'||state.applied.includes(state.request.id))return;state.applied.push(state.request.id);state.appliedCount++;state.request=advance(state.request,'apply');say('Демо-состояние применено один раз. Мир Foundry не изменён.')}else if(action==='next'){if(state.request&&state.request.phase!=='applied')return say('Сначала завершите или отмените текущий запрос.');if(state.role!=='gm'&&['v','n','e'][state.turn]!==state.selected)return say('Сейчас ход другого участника.');state.turn=(state.turn+1)%(state.many?24:3);if(state.turn===0)state.round++;state.request=null;state.panel=null;}else if(action==='target'){state.target='e';say('Выбрана цель. Персонаж и активный ход не изменены.')}else if(action==='reload'){if(state.request&&!['applied'].includes(state.request.phase))return say('Сначала завершите запрос.');state.ammo=8;say('Демо-магазин перезаряжен. Системная экономика действий не выполнялась.')}else if(action==='gm'){if(state.role!=='gm')return;state.panel='gm'}else if(action==='net'){state.panel='net'}else if(action==='flat'){state.netFlat=!state.netFlat}else if(action==='net-demo'){say('Действие NET не подключено к Foundry. Это проверка интерфейса.');return;}else if(action==='compact')state.compact=!state.compact;else if(action==='expand')state.collapsed=!state.collapsed;else if(action==='empty-ammo')state.ammo=0;else if(action==='reset')state={...defaults};else if(action==='reconnect'){save();location.href=location.pathname;return;}else if(action==='resume'){state.panel=state.request?.phase==='awaiting-defense'?'defense':'result'}else if(action==='result'){if(state.request)state.panel='result'}else if(action==='cancel'){if(state.role!=='gm')return;state.request=null;state.panel=null;say('Запрос отменён. Потраченный патрон автоматически не возвращается.')}render();}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){state.panel=null;render()}if(e.key==='h'&&!['INPUT','SELECT'].includes(document.activeElement.tagName)){state.collapsed=!state.collapsed;render()}});window.addEventListener('pagehide',()=>{lifetime.close();clearTimeout(toastTimer)});window.redline={getState:()=>structuredClone(state),publicDefense:()=>publicDefenseProjection(state.request||{}),catalog:operationCatalog};render();
